def level_hand(j1, j4, pitch_up=2.5):
    """j7 that keeps the hand `pitch_up` degrees above horizontal for the arm's j1 and j4 (j2 = j3 = 0)."""
    return (j4 - 90.0 - j1) - pitch_up


# name -> the left arm's joints in degrees. j1 swings the arm back (the hand goes back and down), j2 abducts, j3 turns the forearm out (negative, left), j4 is the elbow, j7 the hand's pitch.
