def mirror(q):
    """The right arm's joints for the left arm's q (radians)."""
    q = np.asarray(q, float)
    return np.array([-q[0], -q[1], -q[2], q[3], -q[4], -q[5], -q[6]])


def set_home(q_left_deg):
    """Applies a home pose (left arm joints in degrees; the right arm is mirrored) to TASK_CFG in this process."""
    ql = tuple(D(v) for v in q_left_deg)
    TASK_CFG["home_q_left"] = ql
    TASK_CFG["home_q_right"] = tuple(float(v) for v in mirror(ql))


class Evaluator:
    """Evaluates the current process's home pose (TASK_CFG) at stances, on the open-bench scene of the finder's case open_b45."""

    def __init__(self):
        self.R = SS.Runner("open_b45", {**SFM.CASES["open_b45"], "cameras": True})
        ctx = self.ctx = self.R.ctx
        self.m, self.data = ctx.m, ctx.data
        self.m.body_pos[self.m.body("task_hotplate").id] = [ctx.hotplate_xy[0], ctx.hotplate_xy[1], ctx.top]
        apply_task_poses(self.m, self.data, {**TASK_CFG, "beaker_xy": tuple(ctx.beaker_xy), "hotplate_xy": tuple(ctx.hotplate_xy)})
        mujoco.mj_forward(self.m, self.data)
        self.chk = StanceChecks(self.m, self.data, ctx.rg["base_z"])
        m = self.m
        body = lambda g: m.body(int(m.geom_bodyid[g])).name
        col = [g for g in range(m.ngeom) if m.geom_contype[g] or m.geom_conaffinity[g]]
        self.groups = {"bench": [g for g in col if body(g) == "bench"], "hotplate+beaker": [g for g in col if body(g) in ("task_hotplate", "task_beaker")],
                       "torso": [g for g in col if body(g) == "openarm_body_link0"], "pedestal": [g for g in col if body(g).startswith("pedestal_")],
                       "base": [g for g in col if body(g) == "base_link" or body(g).endswith(("_link", "_Link"))], "neck": [g for g in col if body(g).startswith("neck_")],
                       "battery": [g for g in col if body(g) == robot_specs.BATTERY_SPECS["name"]]}
        self.groups = {k: v for k, v in self.groups.items() if v}
        self.moving = {sd: [g for g in col if body(g).startswith(f"openarm_{sd}_") and not body(g).endswith(("link0", "link1", "link2"))] for sd in ("left", "right")}
        self.fingers = {sd: [g for g in self.moving[sd] if "finger" in body(g)] for sd in self.moving}
        self.ft = np.zeros(6)

    def refresh_home(self):
        """Re-reads the pose from TASK_CFG (after set_home)."""
        from src.task_beaker_hotplate import home_targets
        self.chk.home = home_targets(self.m, TASK_CFG)

    def _dist(self, a_list, b_list, d):
        best, who = 0.3, ""
        m = self.m
        for a in a_list:
            for b in b_list:
                if m.geom_bodyid[a] == m.geom_bodyid[b]:
                    continue
                if np.linalg.norm(d.geom_xpos[a] - d.geom_xpos[b]) - m.geom_rbound[a] - m.geom_rbound[b] > best:
                    continue
                v = mujoco.mj_geomDistance(m, d, a, b, 0.3, self.ft)
                if v < best:
                    best, who = float(v), f"{m.geom(a).name} vs {m.body(int(m.geom_bodyid[b])).name}"
        return best, who

    def clearances(self, stance):
        """The home_pose_test groups (mm, with the arm part and the other body of the closest pair), the fingers against bench and hotplate, and the beaker on the hotplate."""
        self.chk.place(stance)
        d = self.chk.d
        out = {}
        for name, targets in list(self.groups.items()):
            v, who = min((self._dist(self.moving[sd], targets, d) for sd in ("left", "right")), key=lambda r: r[0])
            out[name] = {"mm": 1000 * v, "pair": who, "min_mm": 1000 * MIN_CLEARANCE[name], "ok": v >= MIN_CLEARANCE[name]}
        v, who = min((self._dist(self.moving["left"], self.moving["right"], d), self._dist(self.moving["right"], self.moving["left"], d)), key=lambda r: r[0])
        out["other arm"] = {"mm": 1000 * v, "pair": who, "min_mm": 1000 * MIN_CLEARANCE["other arm"], "ok": v >= MIN_CLEARANCE["other arm"]}
        for name, grp in (("fingers vs bench", "bench"), ("fingers vs hotplate", "hotplate+beaker")):
            v, who = min((self._dist(self.fingers[sd], self.groups[grp], d) for sd in ("left", "right")), key=lambda r: r[0])
            out[name] = {"mm": 1000 * v, "pair": who}
        bh = self.chk.beaker_on_hotplate_clearance(stance)
        pbm = STANCE_REQUIREMENTS["placed_beaker_min_clearance"]
        out["arms to a beaker standing on the hotplate"] = {"mm": None if bh is None else 1000 * bh, "min_mm": 1000 * pbm, "ok": bh is None or bh >= pbm}
        return out

    def view(self, stance, n=8):
        """The neck spread, the pixel occlusion of the beaker and the hotplate (neck at its framing pose) and the framing slack at a stance."""
        ns = self.chk.neck_spread(stance, n=n)
        occ = self.chk.occlusion(stance, ns["targets"])
        fr = self.chk.framing_slack(stance)
        return {"neck_spread": ns["spread"], "occlusion": occ, "framing_slack_pct": 100 * fr["slack"], "framing_limit": fr["limit"], "framing_pose_free": fr["free"]}

    def tcp(self, stance):
        """Both tool points in the torso's horizontal frame (forward, left, height above the bench top), metres."""
        self.chk.place(stance)
        d = self.chk.d
        x, y, yaw, _ = stance
        c, s = math.cos(yaw), math.sin(yaw)
        top = float(self.ctx.top)
        out = {}
        for sd in ("left", "right"):
            p = d.body(f"openarm_{sd}_hand_tcp").xpos
            out[sd] = [float(c * (p[0] - x) + s * (p[1] - y)), float(-s * (p[0] - x) + c * (p[1] - y)), float(p[2] - top)]
        return out

    def framing(self, stance):
        """The framing slack (percent of the image) with the grippers required in the frame (the staging's requirement) and without them (only the beaker and the hotplate)."""
        with_g, no_g = self.chk.framing_slack(stance), self.chk.framing_slack(stance, grippers=False)
        return {"with_grippers_pct": 100 * with_g["slack"], "with_grippers_limit": with_g["limit"], "without_grippers_pct": 100 * no_g["slack"], "without_grippers_limit": no_g["limit"]}

    def joint_margins(self):
        """Each home joint's distance to its nearer limit, degrees, per arm (the right arm mirrors the left), and the smallest."""
        out = {}
        for sd in ("left", "right"):
            ids = arm_ids(self.m, sd)
            q = np.array(self.chk.home[sd])
            rng = self.m.jnt_range[ids["jnt"]]
            mg = np.degrees(np.minimum(q - rng[:, 0], rng[:, 1] - q))
            out[sd] = [float(v) for v in mg]
        out["min_deg"] = min(min(out["left"]), min(out["right"]))
        return out

    def footprint(self, stance):
        """The footprint seen from above while driving with the arms at home: the chassis polygon (base and battery) and the arms' collision geoms projected into the base frame.

        Returns:
            dict: "chassis_area_m2", "hull_area_m2" (chassis and arms), "arms_front_m" (how far the arms reach forward of the chassis' front edge, negative: inside), "arms_side_m" (how far
            beyond the chassis' side edge, negative: inside), "arms_back_m" (the same behind), the arms' extents "x_range_m" and "y_range_m" in the base frame, and the hull's width.
        """
        self.chk.place(stance)
        m, d = self.m, self.chk.d
        root = m.body("base_link").id
        R, p = d.xmat[root].reshape(3, 3), d.xpos[root]
        pts = []
        for sd in ("left", "right"):
            for g in self.moving[sd] + [g for g in range(m.ngeom) if m.body(int(m.geom_bodyid[g])).name in (f"openarm_{sd}_link1", f"openarm_{sd}_link2") and (m.geom_contype[g] or m.geom_conaffinity[g])]:
                w = geom_points_world(m, d, g)
                if w is not None:
                    pts.append((w - p) @ R)
        P = np.vstack(pts)[:, :2]
        ch = np.asarray(self.ctx.rg["footprint"], float)
        area = lambda Q: float(ConvexHull(Q).volume)
        return {"chassis_area_m2": area(ch), "hull_area_m2": area(np.vstack([ch, P])), "arms_front_m": float(P[:, 0].max() - ch[:, 0].max()), "arms_back_m": float(ch[:, 0].min() - P[:, 0].min()),
                "arms_side_m": float(np.abs(P[:, 1]).max() - np.abs(ch[:, 1]).max()), "x_range_m": [float(P[:, 0].min()), float(P[:, 0].max())], "y_range_m": [float(P[:, 1].min()), float(P[:, 1].max())],
                "hull_width_m": float(np.vstack([ch, P])[:, 1].max() - np.vstack([ch, P])[:, 1].min())}

    def wrist_cameras(self, stance, out_png=None):
        """What the wrist cameras (and the eagle camera) see at the stance with the arms at home and the neck at its framing pose.

        For each wrist camera: how many of the beaker's and the hotplate's 9 points (8 corners and the centre) are in its image and not hidden by another part (rays), and whether its own
        fingertips are in the image; the images are written to out_png (a directory) if given.
        """
        self.chk.place(stance)
        m, d = self.m, self.chk.d
        t1 = self.chk.neck_spread(stance, n=1)["targets"]
        self.chk.place(stance)
        set_neck_pose(m, d, robot_specs.NECK_SPECS, [t1[n] for n in robot_specs.NECK_SPECS["active_joints"]])
        mujoco.mj_forward(m, d)
        pts = dict(view_points(m, d))
        for body, up in (("task_beaker", 0.05), ("task_hotplate", 0.068)):
            pts[body + "_centre"] = d.body(body).xpos + [0, 0, up]
        out = {}
        for sd in ("left", "right"):
            cid = m.camera(f"{sd}_wrist_cam").id
            pos, Rc = d.cam_xpos[cid].copy(), d.cam_xmat[cid].reshape(3, 3)
            fovy, aspect = float(m.cam_fovy[cid]), 640 / 480
            res = {"beaker_in_view": 0, "hotplate_in_view": 0, "beaker_visible": 0, "hotplate_visible": 0, "points_per_object": 9}
            for name, p in pts.items():
                obj = "beaker" if name.startswith("beaker") or name == "task_beaker_centre" else "hotplate" if name.startswith("hotplate") or name == "task_hotplate_centre" else None
                if obj is None:
                    continue
                u, v, dep = _project(np.asarray(p)[None], pos, Rc, fovy, aspect)
                if dep[0] > 0.02 and abs(u[0]) <= 1 and abs(v[0]) <= 1:
                    res[f"{obj}_in_view"] += 1
                    vec = np.asarray(p) - pos
                    dist = float(np.linalg.norm(vec))
                    gid = np.zeros(1, dtype=np.int32)
                    hit = mujoco.mj_ray(m, d, pos, vec / dist, np.array([1, 1, 1, 1, 1, 0], np.uint8), 1, -1, gid)
                    if not (0 <= hit < dist - 0.003 and m.body(int(m.geom_bodyid[gid[0]])).name not in ("task_beaker", "task_hotplate")):
                        res[f"{obj}_visible"] += 1
            tips = np.array([pts[f"{sd}_gripper_tip0"], pts[f"{sd}_gripper_tip1"]])
            u, v, dep = _project(tips, pos, Rc, fovy, aspect)
            res["own_fingertips_in_view"] = int(((dep > 0.02) & (abs(u) <= 1) & (abs(v) <= 1)).sum())
            out[sd] = res
        if out_png is not None:
            Path(out_png).mkdir(parents=True, exist_ok=True)
            gl = mujoco.GLContext(m.vis.global_.offwidth, m.vis.global_.offheight)
            gl.make_current()
            rig = CameraRig(m, robot_specs.CAMERA_SPECS, mujoco.MjrContext(m, mujoco.mjtFontScale.mjFONTSCALE_150))
            rig.render(d)
            for name, img in rig.images.items():
                cv2.imwrite(str(Path(out_png) / f"{name}.png"), cv2.cvtColor(img, cv2.COLOR_RGB2BGR))
            out["images"] = sorted(str(Path(out_png) / f"{n}.png") for n in rig.images)
            del rig, gl
        return out

    def occlusion_area(self, stance):
        """The pixel occlusion at the stance with the neck at its framing pose (src/stance_checks.OcclusionMeter): "beaker_hidden_frac", "hotplate_hidden_frac" and the pixel counts."""
        return self.chk.occlusion(stance)

    def to_pregrasp(self, stance, speed=0.5):
        """The left arm's move from home to the pre-grasp pose (the IK waypoint above and behind the beaker, experiments/grasp_ik_targets.py) at a joint speed limit.

        Returns:
            dict: "max_joint_change_rad" (the largest joint travel), "seconds_constant_speed" (that travel at `speed` rad/s, the quickest possible) and "seconds_min_jerk" (a minimum-jerk move
            whose peak joint speed is `speed`: 1.875 times the travel over the time), the same for home -> grasp, and the targets' joint margin and clearance; or an "error" string.
        """
        self.chk.place(stance)
        try:
            t = grasp_targets(self.m, self.chk.d, "left")
        except RuntimeError as e:
            return {"error": str(e)}
        home = np.array(self.chk.home["left"])
        out = {"speed_rad_s": speed, "bin": t["bin"], "joint_margin_deg_of_targets": t["joint_margin_deg"], "target_clearance_mm": t["clearance_mm"]}
        for key, q in (("pregrasp", t["ready_q"]), ("grasp", t["grasp_q"])):
            dq = float(np.abs(q - home).max())
            out[key] = {"max_joint_change_rad": dq, "seconds_constant_speed": dq / speed, "seconds_min_jerk": 1.875 * dq / speed, "q_deg": [float(v) for v in np.degrees(q)]}
        return out

    def full(self, stance, out_png=None):
        r = {"stance": [float(stance[0]), float(stance[1]), math.degrees(stance[2]), float(stance[3])], "tcp_fwd_left_up_m": self.tcp(stance), "clearance": self.clearances(stance), **self.view(stance),
             "framing": self.framing(stance), "joint_margins_deg": self.joint_margins(), "footprint": self.footprint(stance), "to_pregrasp": self.to_pregrasp(stance), "wrist_cameras": self.wrist_cameras(stance, out_png)}
        return r


def fmt_full(r):
    c, f, fp, w = r["clearance"], r["framing"], r["footprint"], r["wrist_cameras"]
    t = r["to_pregrasp"]
    lines = [f"  stance x {r['stance'][0]:.3f} y {r['stance'][1]:.3f} heading {r['stance'][2]:.0f} pedestal {r['stance'][3]:.3f}; tool point left (forward, left, above bench top, m) {np.round(r['tcp_fwd_left_up_m']['left'], 3).tolist()}",
             "  clearance (mm; minimum): " + ", ".join(f"{k} {v['mm']:.0f}{'' if v.get('ok', True) else '!'}" for k, v in c.items() if k in MIN_CLEARANCE),
             f"  fingers vs bench {c['fingers vs bench']['mm']:.0f} mm ({c['fingers vs bench']['pair']}), fingers vs hotplate {c['fingers vs hotplate']['mm']:.0f} mm ({c['fingers vs hotplate']['pair']}), arms to a beaker on the hotplate {c['arms to a beaker standing on the hotplate']['mm']} mm",
             f"  occlusion by the robot (pixels, eagle camera): beaker {100 * r['occlusion']['beaker_hidden_frac']:.1f} % hidden ({r['occlusion']['beaker_px']} of {r['occlusion']['beaker_px_free']} px; {100 * OCC_MAX['beaker']:.0f} % allowed), "
             f"hotplate {100 * r['occlusion']['hotplate_hidden_frac']:.1f} % hidden ({r['occlusion']['hotplate_px']} of {r['occlusion']['hotplate_px_free']} px; {100 * OCC_MAX['hotplate']:.0f} % allowed); neck spread {r['neck_spread']:.3f} rad (0.06 allowed)",
             f"  framing slack with the grippers in frame {f['with_grippers_pct']:.1f} % (limit {f['with_grippers_limit']}), without {f['without_grippers_pct']:.1f} % (limit {f['without_grippers_limit']}); 10 % required",
             f"  joint margins (deg) left {np.round(r['joint_margins_deg']['left'], 0).tolist()}, smallest {r['joint_margins_deg']['min_deg']:.0f}",
             f"  driving footprint: hull {fp['hull_area_m2']:.3f} m2 against the chassis {fp['chassis_area_m2']:.3f}; arms {1000 * fp['arms_front_m']:+.0f} mm past the front edge, {1000 * fp['arms_side_m']:+.0f} mm past the side edge, {1000 * fp['arms_back_m']:+.0f} mm behind; width {1000 * fp['hull_width_m']:.0f} mm",
             "  wrist cameras: " + "; ".join(f"{sd}: beaker {w[sd]['beaker_visible']}/9, hotplate {w[sd]['hotplate_visible']}/9 points seen, own fingertips in view {w[sd]['own_fingertips_in_view']}/2" for sd in ("left", "right")),
             "  home -> pre-grasp at 0.5 rad/s: " + (t["error"] if "error" in t else f"largest joint change {t['pregrasp']['max_joint_change_rad']:.2f} rad = {t['pregrasp']['seconds_constant_speed']:.1f} s at constant speed, {t['pregrasp']['seconds_min_jerk']:.1f} s with a minimum-jerk profile; home -> grasp {t['grasp']['seconds_min_jerk']:.1f} s")]
    return "\n".join(lines)


def probe(ev, name, q_deg, heights, n=4):
    set_home(q_deg)
    ev.refresh_home()
    t = time.time()
    tcp = ev.tcp(CURRENT_STANCE)
    row = []
    for h in heights:
        st = (*CURRENT_STANCE[:3], h)
        c = ev.clearances(st)
        env_ok = all(v["ok"] for k, v in c.items() if k in MIN_CLEARANCE)                 # the home_pose_test groups; the beaker-on-hotplate clearance is a flag (*) beside it
        worst = min((v for k, v in c.items() if k in MIN_CLEARANCE), key=lambda v: v["mm"] - v["min_mm"])
        star = "" if c["arms to a beaker standing on the hotplate"]["ok"] else "*"
        if env_ok:
            vw = ev.chk.neck_spread(st, n=n)
            oc = ev.chk.occlusion(st, vw["targets"]) if vw["spread"] <= SFM.NECK_MAX_SPREAD else None
            tag = "Hn" if oc is None else "HNO" if occlusion_ok(oc) else "HNo"
            row.append((h, tag + star, worst["mm"] - worst["min_mm"], vw["spread"], oc))
        else:
            row.append((h, "h" + star, worst["mm"] - worst["min_mm"], None, []))
    print(f"{name}: q {list(map(float, np.round(q_deg, 1)))} tool point left {np.round(tcp['left'], 3).tolist()} ({time.time() - t:.0f} s)")
    print("    " + " ".join(f"{h:.2f}:{s}({m:+.0f})" for h, s, m, _, _ in row), flush=True)
    return row


def grid_candidates():
    """A grid of poses that keep the zombie pose's character: the forearm 5 to 25 degrees above horizontal, the hand level, the elbow bent 90 to 140 degrees."""
    out = {}
    for j1, pitch, j3 in itertools.product((12.5, 20.0, 28.0, 36.0), (5.0, 15.0, 25.0), (0.0, -10.0, -20.0)):
        j4 = pitch + 90.0 + j1
        if j4 > 138.0:
            continue
        out[f"j1_{j1:g}_pitch_{pitch:g}_j3_{-j3:g}"] = (j1, 0.0, j3, j4, 0.0, 0.0, level_hand(j1, j4))
    return out


def run_finder(name, q_deg, out_dir, args):
    """The full evaluation of one pose: detail at the current stance, the finder rerun, detail at the chosen stance (with the images), the xy region."""
    import gc
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    set_home(q_deg)
    ev = Evaluator()
    res = {"name": name, "left_q_deg": list(map(float, q_deg)), "right_q_deg": [float(v) for v in np.degrees(mirror(np.radians(q_deg)))]}
    res["at_current_stance"] = ev.full(CURRENT_STANCE, out_png=out_dir / "at_current_stance")
    print(f"=== {name}: left arm {list(map(float, q_deg))} deg\nat the current stance:\n{fmt_full(res['at_current_stance'])}", flush=True)
    del ev                                                         # the finder builds its own scene (the Runner of select_stance); free this one first
    gc.collect()
    sel_args = types.SimpleNamespace(heading=-90.0, n_cand=12, q_step=0.01, nms=0.04, out=str(out_dir), xy_half=args.xy_half, xy_step=args.xy_step)
    maps = SFM.load_maps(PROJECT_ROOT / "data" / "reach_map")
    sel = SFM.select_stance("open_b45", sel_args, maps)
    res["finder"] = {"chosen": sel["chosen"], "seconds": sel["seconds"], "candidates": [{k: v for k, v in e.items() if k != "rows"} for e in sel["candidates"]]}
    ch = sel["chosen"]
    if ch:
        gc.collect()
        ev2 = Evaluator()
        st = (ch["x"], ch["y"], math.radians(ch["heading_deg"]), ch["q"])
        res["at_chosen_stance"] = ev2.full(st, out_png=out_dir / "at_chosen_stance")
        print(f"at the chosen stance:\n{fmt_full(res['at_chosen_stance'])}", flush=True)
    SFM.save(out_dir / "summary.json", res)
    return res


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("--probe", nargs="*", default=None)
    ap.add_argument("--scan", action="store_true")
    ap.add_argument("--finder", nargs="*", default=None)
    ap.add_argument("--detail", nargs="*", default=None, help="the full detail at the current stance only (no finder rerun)")
    ap.add_argument("--heights", type=float, nargs="*", default=[round(x, 2) for x in np.arange(0.06, 0.2401, 0.03)])
    ap.add_argument("--out", default=str(PROJECT_ROOT / "data" / "home_pose_candidates"))
    ap.add_argument("--xy-half", type=float, default=0.06, help="--finder: half width of the xy grid around the chosen stance, m")
    ap.add_argument("--xy-step", type=float, default=0.02, help="--finder: the xy grid step, m")
    args = ap.parse_args()
    for name in args.detail or []:
        set_home(CANDIDATES[name])
        ev = Evaluator()
        r = ev.full(CURRENT_STANCE, out_png=Path(args.out) / name / "at_current_stance")
        print(f"=== {name}\n{fmt_full(r)}", flush=True)
        SFM.save(Path(args.out) / name / "at_current_stance.json", r)
        del ev
    ev = Evaluator() if (args.scan or args.probe) else None
    if args.scan:
        for name, q in grid_candidates().items():
            probe(ev, name, q, args.heights)
    if args.probe:
        for name in args.probe:
            probe(ev, name, CANDIDATES[name], args.heights)
    if args.finder:
        for name in args.finder:
            run_finder(name, CANDIDATES[name], Path(args.out) / name, args)


if __name__ == "__main__":
    main()
